// === Tab: sketch ===
// By Roni Kaufman
// https://ronikaufman.github.io

const N_FRAMES = 180;

function setup() {
	createCanvas(500, 500);
	stroke("#050505");
	noFill();
}

function draw() {
	background("#fffcf2");

	let t = (frameCount%N_FRAMES)/N_FRAMES;

	let n = 9;
	let margin = 60, gap = 10;
	strokeWeight(gap/2);
	let s = (width-2*margin-(n-1)*gap)/n;
	for (let j = 0; j < n; j++) {
		let y = margin + j*(s+gap) + s/2;
		for (let i = 0; i < n; i++) {
			let x = margin + i*(s+gap) + s/2;
			let offset = 2-max(abs(1/2+i-n/2), abs(1/2+j-n/2))/((n-1));
			squareArrow(x, y, s/2, (t+offset)%1);
		}
	}
}

function squareArrow(xC, yC, s, t) {
	t = easeInOutQuart(4*(t%(1/4)))/4 + ~~(t*4)/4 + 1/8;
	let theta0 = TAU*t;

	let nextCorner = 1/8;
	if (t < 7/8) nextCorner = 7/8;
	if (t < 5/8) nextCorner = 5/8;
	if (t < 3/8) nextCorner = 3/8;
	if (t < 1/8) nextCorner = 1/8;
	let theta1 = nextCorner*TAU;
	let theta2 = (nextCorner+1/4)*TAU;
	let theta3 = theta0 + PI;

	let [x0, y0] = getPoint(xC, yC, s, theta0);
	let [x1, y1] = getPoint(xC, yC, s, theta1);
	let [x2, y2] = getPoint(xC, yC, s, theta2);
	let [x3, y3] = getPoint(xC, yC, s, theta3);
	strokeCap(PROJECT);
	beginShape();
	vertex(x0, y0);
	vertex(x1, y1);
	vertex(x2, y2);
	vertex(x3, y3);
	endShape();

	let middle = theta0 + HALF_PI;
	let [xLine1, yLine1] = getPoint(xC, yC, s, middle);
	let [xLine2, yLine2] = getPoint(xC, yC, s, middle+PI);
	strokeCap(SQUARE);
	line(xLine1, yLine1, xLine2, yLine2);
}

function getPoint(xC, yC, rMax, theta) {
	let r = rMax*getLengthForDeg(theta);
	let x = xC + r*cos(theta);
	let y = yC + r*sin(theta);
	return [x, y];
}

// adapted from https://stackoverflow.com/questions/4788892/draw-square-with-polar-coordinates
function getLengthForDeg(phi) {
    phi = ((phi+QUARTER_PI)%HALF_PI-QUARTER_PI);
    return 1/cos(phi);
}

// adapted from easings.net
function easeInOutQuart(x) {
	return x < 0.5 ? 8 * x * x * x * x : 1 - Math.pow(-2 * x + 2, 4) / 2;
}

// 1. 免疫 DOM 元素建立導致的看門狗攔截
if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
if (typeof createDiv === 'undefined') { window.createDiv = function() { return { position: function(){}, style: function(){} }; }; }

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || (path.startsWith('http') === false && path.startsWith('data:') === false)) {
            // 當發現是相對路徑或丟失的外部圖片資產時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (this.width === 0 || this.height === 0) {
            return createGraphics(10, 10);
        }
        return window._origGet.apply(this, args);
    };
}
